import { mkdir } from 'node:fs/promises';
import { join } from 'node:path';
import { writeTextFileSafe } from '../../../../../../../scripts/helpers/file/write-text-file-safe.ts';
import {
  ANDROID_ICON_PACK_NAME,
  ANDROID_ICON_SIZES,
  ANDROID_ICONS_PACKAGE_NAME,
  ANDROID_IMAGE_VECTORS_PACKAGE_NAME,
  ANDROID_SYMBOL_INTERFACE_NAME,
  ANDROID_SYMBOLS_PACKAGE_NAME,
  type AndroidIconSize,
} from './android-icons-config.ts';

const SYMBOL_FILE_HEADER =
  '// This file is auto-generated by the Android icons build of the Infomaniak design-system repository. Do not edit it manually.';

export interface GenerateAndroidSymbolsOptions {
  /** Directory the `<IconName>.kt` files are written into. */
  readonly outputDirectory: string;
  /** Icon names (file names without extension) generated for each size. */
  readonly iconNamesBySize: ReadonlyMap<string, readonly string[]>;
}

/**
 * Writes one `<IconName>.kt` file per icon, exposing `EsdsIcons.<IconName>` as a `Symbol` grouping
 * every size.
 *
 * @throws if an icon is missing in one of the sizes.
 * @returns the sorted list of icon names.
 */
export async function generateAndroidSymbols({
  outputDirectory,
  iconNamesBySize,
}: GenerateAndroidSymbolsOptions): Promise<readonly string[]> {
  const iconNames: readonly string[] = getAndroidSymbolIconNames(iconNamesBySize);

  await mkdir(outputDirectory, { recursive: true });

  await Promise.all(
    iconNames.map((iconName: string): Promise<void> => {
      return writeTextFileSafe(
        join(outputDirectory, `${iconName}.kt`),
        buildAndroidSymbolFile(iconName),
      );
    }),
  );

  return iconNames;
}

function getAndroidSymbolIconNames(
  iconNamesBySize: ReadonlyMap<string, readonly string[]>,
): readonly string[] {
  const iconNames: readonly string[] = [
    ...new Set(ANDROID_ICON_SIZES.flatMap(({ name }) => iconNamesBySize.get(name) ?? [])),
  ].sort();

  const missingIcons: readonly string[] = ANDROID_ICON_SIZES.flatMap(
    ({ name }: AndroidIconSize): readonly string[] => {
      const sizeIconNames: ReadonlySet<string> = new Set(iconNamesBySize.get(name));

      return iconNames
        .filter((iconName: string): boolean => !sizeIconNames.has(iconName))
        .map((iconName: string): string => `${name}.${iconName}`);
    },
  );

  if (missingIcons.length > 0) {
    throw new Error(`Icons missing in some sizes: ${missingIcons.join(', ')}.`);
  }

  return iconNames;
}

export function buildAndroidSymbolFile(iconName: string): string {
  const objectName: string = `${iconName}${ANDROID_SYMBOL_INTERFACE_NAME}`;

  const sizeImports: string = ANDROID_ICON_SIZES.map(({ name }: AndroidIconSize): string => {
    return `import ${ANDROID_IMAGE_VECTORS_PACKAGE_NAME}.${name.toLowerCase()}.${iconName}`;
  }).join('\n');

  const sizeProperties: string = ANDROID_ICON_SIZES.map(({ name }: AndroidIconSize): string => {
    return `    override val ${name}: ImageVector get() = ${ANDROID_ICON_PACK_NAME}.${name}.${iconName}`;
  }).join('\n');

  return `${SYMBOL_FILE_HEADER}
package ${ANDROID_SYMBOLS_PACKAGE_NAME}

import androidx.compose.ui.graphics.vector.ImageVector
import ${ANDROID_ICONS_PACKAGE_NAME}.${ANDROID_ICON_PACK_NAME}
${sizeImports}

val ${ANDROID_ICON_PACK_NAME}.${iconName}: ${ANDROID_SYMBOL_INTERFACE_NAME} get() = ${objectName}

private object ${objectName} : ${ANDROID_SYMBOL_INTERFACE_NAME} {
${sizeProperties}
}
`;
}
